```tsx
import React, { useState, useMemo, useRef, useEffect } from 'react';

type Option = string;

interface InputProps {
  options: Option[];
  placeholder?: string;
  validate?: (value: string) => boolean;
}

const Input: React.FC<InputProps> = ({ options, placeholder, validate }) => {
  const [inputValue, setInputValue] = useState('');
  const [showDropdown, setShowDropdown] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Filter options based on input
  const filteredOptions = useMemo(() => {
    const v = inputValue.trim().toLowerCase();
    if (!v) return [];
    return options.filter(option =>
      option.toLowerCase().includes(v)
    );
  }, [inputValue, options]);

  // Use Set for fast validation if no custom function
  const fastOptionSet = useMemo(() => new Set(options.map(opt => opt.toLowerCase())), [options]);
  const isValid = useMemo(() => {
    if (validate) return validate(inputValue);
    if (!inputValue) return true;
    return fastOptionSet.has(inputValue.toLowerCase());
  }, [inputValue, validate, fastOptionSet]);

  // Hide dropdown on outside click
  useEffect(() => {
    if (!showDropdown || !isFocused) return;
    const handleClick = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
        setIsFocused(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showDropdown, isFocused]);

  return (
    <div ref={containerRef} style={{ position: 'relative', width: 300 }}>
      <input
        type="text"
        value={inputValue}
        placeholder={placeholder}
        onChange={e => {
          setInputValue(e.target.value);
          setShowDropdown(!!e.target.value && filteredOptions.length > 0);
        }}
        onFocus={() => {
          setIsFocused(true);
          setShowDropdown(!!inputValue && filteredOptions.length > 0);
        }}
        style={{
          border: `2px solid ${isValid ? '#ccc' : 'red'}`,
          borderRadius: 4,
          padding: '8px',
          width: '100%',
          fontSize: 16,
        }}
      />
      {(showDropdown && filteredOptions.length > 0) && (
        <div
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            right: 0,
            background: '#fff',
            border: '1px solid #ccc',
            zIndex: 100,
            maxHeight: 200,
            overflowY: 'auto',
          }}
        >
          {filteredOptions.map((option, idx) => (
            <div
              key={option}
              style={{ padding: 8, cursor: 'pointer' }}
              onMouseDown={() => { // onMouseDown so input doesn’t blur
                setInputValue(option);
                setShowDropdown(false);
              }}
            >
              {option}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
```

**Optimizations and Features:**
