#include <fstream>
#include <unistd.h> // for sleep()
#include <iostream>

int main() {
    // 1. Export GPIO pins so Linux creates the needed directories.
    // Motor 1 uses GPIO17 (IN1), GPIO18 (IN2)
    // Motor 2 uses GPIO22 (IN3), GPIO23 (IN4)

    std::ofstream export_file("/sys/class/gpio/export");
    if (!export_file) { std::cerr << "Error exporting GPIO"; return 1; }
    export_file << "17";
    export_file.close();

    export_file.open("/sys/class/gpio/export");
    export_file << "18";
    export_file.close();

    export_file.open("/sys/class/gpio/export");
    export_file << "22";
    export_file.close();

    export_file.open("/sys/class/gpio/export");
    export_file << "23";
    export_file.close();

    sleep(1); // Wait to ensure the system creates gpioN directories

    // 2. Set direction for each GPIO as output
    std::ofstream dir17("/sys/class/gpio/gpio17/direction");
    dir17 << "out";
    dir17.close();

    std::ofstream dir18("/sys/class/gpio/gpio18/direction");
    dir18 << "out";
    dir18.close();

    std::ofstream dir22("/sys/class/gpio/gpio22/direction");
    dir22 << "out";
    dir22.close();

    std::ofstream dir23("/sys/class/gpio/gpio23/direction");
    dir23 << "out";
    dir23.close();

    // 3. Set values to run both motors forward.
    // Motor 1 Forward: IN1=1, IN2=0
    // Motor 2 Forward: IN3=1, IN4=0
    std::ofstream val17("/sys/class/gpio/gpio17/value");
    val17 << "1";
    val17.close();

    std::ofstream val18("/sys/class/gpio/gpio18/value");
    val18 << "0";
    val18.close();

    std::ofstream val22("/sys/class/gpio/gpio22/value");
    val22 << "1";
    val22.close();

    std::ofstream val23("/sys/class/gpio/gpio23/value");
    val23 << "0";
    val23.close();

    sleep(5); // Run motors for 5 seconds

    // 4. To stop the motors, set both inputs for each motor LOW.
    val17.open("/sys/class/gpio/gpio17/value");
    val17 << "0";
    val17.close();

    val18.open("/sys/class/gpio/gpio18/value");
    val18 << "0";
    val18.close();

