    for (size_t i = 0; i < n; ++i) x_orig[i] = i;

    // 47 points evenly from 0 to 9 (n-1)
    size_t num_points = 47;
    std::vector<double> x_new(num_points);
    double x_min = 0, x_max = n-1;
    for (size_t i = 0; i < num_points; ++i)
        x_new[i] = x_min + (x_max - x_min) * i / (num_points - 1);

    // Interpolate
    std::vector<double> y_new(num_points);
    for (size_t i = 0; i < num_points; ++i)
