    vector<double> x_original(n);
    for (int i = 0; i < n; ++i) x_original[i] = i;

    // linspace from 0 to n-1, 47 points
    int n_new = 47;
    vector<double> x_new(n_new);
    for (int i = 0; i < n_new; ++i) {
        x_new[i] = 0.0 + i * (n-1) / double(n_new - 1);
    }

