let x;

$: (async () => {
  const fixedVar = x;
  const result = await f(fixedVar);
  if (fixedVar === x) {
    finalResult = result;
  }
})();
```
This structure is almost identical in logic to the original, just using async/await for more readable code.

**2. Extract to an Explicit Function**

Instead of inlining everything, factoring out the async operation into a function:

```svelte
let finalResult;
let x;

async function updateFinalResult(currentX) {
  const result = await f(currentX);
  if (currentX === x) finalResult = result;
}

$: updateFinalResult(x);
```
This provides better separation of concerns and can make error handling easier.

**3. Using a Svelte Store (for complex or shared scenarios)**

If the loading or result state is needed across components or has more states (like loading/error), a Svelte store can encapsulate the async logic:

```js
import { writable } from 'svelte/store';

function asyncResult(func, arg) {
  const { subscribe, set } = writable(null);
  let current = arg;
  async function run(val) {
    current = val;
    const result = await func(val);
    if (current === val) set(result);
  }
  run(arg);
  return {
    subscribe,
    setArg: run
  }
}
```
This kind of structure may be overkill for simple needs, but it's useful in larger apps.

**4. Promise Version with Cancellation (for advanced scenarios)**

Track the "latest" promise and only update result if the promise is still current:

```svelte
let finalResult;
let x;
let currentPromiseId = 0;

$: {
  const myPromiseId = ++currentPromiseId;
  f(x).then(result => {
    if (myPromiseId === currentPromiseId) finalResult = result;
  });
}
```
This is a bit more robust if `x` can change rapidly.

**Missing but Important:**

- All these approaches can benefit from error handling.
- If the async function supports it, using an AbortController pattern is even more robust.
