**My Answer (Production-ready Expandable Text Component)**

In React Native, a production-ready "ExpandableText" component should render only one line if the text is longer than one line, add a "See more" link at the end, and, when pressed, expand to show all the text.

The most reliable way is to use `onTextLayout` to detect truncation and leverage state to control expansion. Inline "See more" is preferred for better user experience (making it appear at the end of line). Here's a robust implementation:

```jsx
import React, { useState, useCallback } from 'react';
import { Text, StyleSheet, TouchableOpacity } from 'react-native';

const ExpandableText = ({
  text,
  style,
  seeMoreText = ' See more',
  seeMoreStyle,
  numberOfLines = 1,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showSeeMore, setShowSeeMore] = useState(false);

  const onTextLayout = useCallback(e => {
    // Determine if truncation is needed
    setShowSeeMore(e.nativeEvent.lines.length > numberOfLines);
  }, [numberOfLines]);

  return (
    <Text
      style={[styles.text, style]}
      numberOfLines={isExpanded ? 0 : numberOfLines}
      onTextLayout={onTextLayout}
    >
      {text}
      {/* Only show See more if truncated and not expanded */}
      {
        !isExpanded && showSeeMore &&
        <Text style={[styles.seeMore, seeMoreStyle]} onPress={() => setIsExpanded(true)}>
          {seeMoreText}
        </Text>
      }
    </Text>
  );
};

const styles = StyleSheet.create({
  text: {
    color: '#222',
    fontSize: 16,
  },
  seeMore: {
    color: '#007AFF',
    fontWeight: 'bold',
  }
});

export default ExpandableText;
```

