        auto new_node = std::make_unique<Node>(value);
        new_node->next = std::move(head);
        head = std::move(new_node);
    }

    void print() const {
        const Node* current = head.get();
        while (current) {
            std::cout << current->data << " -> ";
            current = current->next.get();
        }
        std::cout << "nullptr\n";
    }
};

int main() {
    LinkedList list;
    list.push_front(1);
    list.push_front(2);
    list.push_front(3);
    list.print();
    // When 'list' goes out of scope, all memory is automatically freed.
    return 0;
}
```

**Notes:**
- `std::unique_ptr` recursively destroys the nodes starting from the list's head when the owning `LinkedList` object is destroyed.
- If your data structure contains cycles (rare for singly linked lists but possible for doubly/circular lists), you would need `std::shared_ptr` for shared ownership and `std::weak_ptr` to break cycles, otherwise memory leaks may occur.

**Summary:** Use smart pointers for safe and automatic memory reclamation in C++ linked lists instead of explicit `delete` calls.

