#include <QCoreApplication>
#include <QXlsx/xlsxdocument.h>
#include <QVariant>
#include <QSet>
#include <QString>
#include <QDebug>

// Helper: parse string in any accepted base
bool parseStringValue(const QString &str, int &number) {
    QString s = str.trimmed();
    bool ok = false;

    // Hexadecimal (0x...)
    if (s.startsWith("0x", Qt::CaseInsensitive))
        number = s.mid(2).toInt(&ok, 16);
    // Binary (0b...)
    else if (s.startsWith("0b", Qt::CaseInsensitive)) {
        number = s.mid(2).toInt(&ok, 2);
    }
    // Octal (leading 0, more than one digit)
    else if (s.startsWith('0') && s.length() > 1)
        number = s.toInt(&ok, 8);
    // Decimal integer
    else
        number = s.toInt(&ok, 10);

    // Also try float and check if it's integer
    if (!ok) {
        double d = s.toDouble(&ok);
        if (ok && std::fabs(d - int(d)) < 1e-8) {
            number = int(d);
            ok = true;
        }
    }
    return ok;
}

// Main check function
bool checkCellValue(const QVariant &cellValue, int &numberOut) {
    bool ok = false;
    if (cellValue.type() == QVariant::Double || cellValue.canConvert<double>()) {
        double d = cellValue.toDouble(&ok);
        if (ok && std::fabs(d - int(d)) < 1e-8) {
            numberOut = int(d);
            return true;
        }
    }
    QString str = cellValue.toString();
    return parseStringValue(str, numberOut);
}

int main(int argc, char *argv[]) {
    QCoreApplication app(argc, argv);

    // Expect: program <file.xlsx> <cell>
    if (argc != 3) {
        qWarning() << "Usage:" << argv[0] << "<file.xlsx> <cell>";
        return 1;
    }
    QString filename = argv[1];
    QString cell = argv[2];

    QXlsx::Document xlsx(filename);
    if (!xlsx.load()) {
        qWarning() << "Failed to open file:" << filename;
        return 1;
    }
    QVariant v = xlsx.read(cell);
    if (!v.isValid()) {
        qWarning() << "Invalid cell or empty cell:" << cell;
        return 1;
    }

    int n = 0;
    if (!checkCellValue(v, n)) {
        qDebug() << "Cell" << cell << "could not be interpreted as a valid integer.";
        return 1;
    }

    QSet<int> allowed = {0, 1, 2, 3, 10, 11, 42};
    if (allowed.contains(n))
        qDebug() << "Cell" << cell << "contains an allowed value:" << n;
    else
        qDebug() << "Cell" << cell << "value" << n << "is not allowed!";
    return 0;
}
```

