**Restatement:**  
Given an Excel table and a cell number, using C++, Qt, and QXlsx, check that the cell contains either the number 0, 1, 2, 3, 10, 11, or 42. The number may be of any numeric type (int, float, etc.) or may be represented as hex, dec, oct, or binary string.

## Key Steps

1. Use QXlsx to load the Excel file.
2. Read the cell's value as a QVariant.
3. If it is numeric, check if it's an integer (zero decimal part), then test if the value is in the allowed set.
4. If it is a string, determine its base:
   - If it starts with `0x` or `0X`, parse as hex.
   - If it starts with `0b` or `0B`, parse as binary.
   - If it starts with `0` and length > 1, parse as octal.
   - Otherwise, try to parse as decimal.
   - Also, consider strings containing float representations like "3.0".
5. After parsing, test if the result is *exactly* one of the allowed values.

## Example Code

```cpp
#include <QCoreApplication>
#include <QXlsx/xlsxdocument.h>
#include <QXlsx/xlsxcell.h>
#include <QDebug>
#include <QVariant>
#include <QSet>

bool parseNumber(const QVariant &var, int &number) {
    bool okInt = false, okDouble = false;
    QSet<int> allowed = {0, 1, 2, 3, 10, 11, 42};

    // First, try to convert as a double
    double d = var.toDouble(&okDouble);
    if (okDouble) {
        int asInt = static_cast<int>(d);
        if (qFuzzyCompare(d + 1, asInt + 1)) {
            number = asInt;
            return allowed.contains(number);
        } else {
            return false; // It's not integer
        }
    }
    // Try to convert as string
    QString s = var.toString().trimmed();
    if (s.isEmpty())
        return false;

    // Hex, octal, binary
    if (s.startsWith("0x", Qt::CaseInsensitive)) {
        number = s.mid(2).toInt(&okInt, 16);
    } else if (s.startsWith("0b", Qt::CaseInsensitive)) {
        number = s.mid(2).toInt(&okInt, 2);
    } else if (s.startsWith("0") && s.length() > 1) {
        number = s.toInt(&okInt, 8);
    } else {
        number = s.toInt(&okInt, 10);
        if (!okInt) {
            // Try as double, but must be exact integer
            d = s.toDouble(&okDouble);
            if (okDouble) {
                int asInt = static_cast<int>(d);
                if (qFuzzyCompare(d + 1, asInt + 1)) {
                    number = asInt;
                    okInt = true;
                }
            }
        }
    }
    return okInt && allowed.contains(number);
}


int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    if (argc != 3) {
        qWarning() << "Usage: excel_check <filename.xlsx> <cell-reference>";
        return 1;
    }

    QString filename = argv[1];
    QString cellAddr = argv[2];

    QXlsx::Document xlsx(filename);
    if (!xlsx.load()) {
        qWarning() << "Failed to open file" << filename;
        return 1;
    }
    QVariant val = xlsx.read(cellAddr);
    if (!val.isValid()) {
        qWarning() << "Cell is empty or invalid";
        return 1;
    }

    int number;
    if (parseNumber(val, number)) {
        qDebug() << "Cell" << cellAddr << "contains an allowed number:" << number;
    } else {
        qDebug() << "Cell" << cellAddr << "does NOT contain a valid allowed number.";
    }

    return 0;
}
```

**Notes:**  
