class RecorderViewModel: ObservableObject {
    @Published var isRecording = false
    @Published var levels: [CGFloat] = [0,0,0,0,0]
    @Published var savedURL: URL? = nil

    private var timer: Timer?
    private let audioManager = AudioManager()

    func start() {
        audioManager.startRecording { [weak self] success in
            DispatchQueue.main.async {
                guard let self = self else { return }
                if success {
                    self.isRecording = true
                    self.timer = Timer.scheduledTimer(withTimeInterval: 0.05, repeats: true) { _ in
                        let level = self.audioManager.currentPower()
                        let normalized = Self.normalize(level)
                        self.levels.removeLast()
                        self.levels.insert(CGFloat(normalized), at: 0)
                    }
                }
            }
        }
    }
    func stop() {
        isRecording = false
        audioManager.stopRecording()
        savedURL = audioManager.recordingURL
        timer?.invalidate()
        timer = nil
    }

    static func normalize(_ db: Float) -> CGFloat {
        let clamped = min(0, max(-60, db)) // typical db range for voice
        return CGFloat((clamped + 60) / 60) // [0 - 1]
    }
}
