}

struct Game {
    var points: [Point] = []
    var player1Points: Int = 0
    var player2Points: Int = 0
    var winner: Int? = nil // 1, 2, or nil if ongoing
}

struct SetScore {
    var gamesWon: [Int] = [0, 0]
    var games: [Game] = []
    var winner: Int? = nil
}

class TennisMatch: ObservableObject {
    @Published var setScores: [SetScore] = Array(repeating: SetScore(), count: 3)
    @Published var currentSet: Int = 0
    @Published var currentGame: Game = Game()
    @Published var matchWinner: Int? = nil
    @Published var advancedMode: Bool = false

