    func addPoint(player: Int, detail: PointDetail? = nil) {
        guard matchWinner == nil else { return }

        currentGame.points.append(Point(player: player, detail: detail))
        if player == 1 {
            currentGame.player1Points += 1
        } else {
            currentGame.player2Points += 1
        }
        processGameLogic()
    }

    private func processGameLogic() {
        // Simplified tennis scoring (add actual deuce/advantage logic as needed)
        let p1 = currentGame.player1Points
        let p2 = currentGame.player2Points
        if p1 >= 4 && p1 > p2 + 1 {
            winGame(player: 1)
        } else if p2 >= 4 && p2 > p1 + 1 {
            winGame(player: 2)
        }
    }

    private func winGame(player: Int) {
        setScores[currentSet].games.append(currentGame)
        setScores[currentSet].gamesWon[player-1] += 1
        currentGame = Game()
        checkSetWin()
    }

    private func checkSetWin() {
        let games = setScores[currentSet].gamesWon
        if games[0] >= 6 && games[0] > games[1] + 1 {
            setScores[currentSet].winner = 1
        } else if games[1] >= 6 && games[1] > games[0] + 1 {
            setScores[currentSet].winner = 2
        }
        if let setWinner = setScores[currentSet].winner {
            // Check for match win (best of 3 sets)
            let p1Sets = setScores.filter { $0.winner == 1 }.count
            let p2Sets = setScores.filter { $0.winner == 2 }.count
            if p1Sets == 2 {
                matchWinner = 1
            } else if p2Sets == 2 {
                matchWinner = 2
            } else if currentSet + 1 < 3 {
                currentSet += 1
            }
        }
    }
}

