Directly marshalling a `HashSet<string>` in C# into bytes using very low-level memory operations (like `Marshal.StructureToPtr`) is not feasible, since `HashSet<string>` is a managed, reference-typed collection with an internal structure subject to change and containing references (not blittable). However, if your goal is to manually serialize/deserialize a `HashSet<string>` into a compact, low-level byte format (not using built-in serialization but writing everything yourself), you can do the following:

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public static class HashSetStringBinary
{
    public static byte[] Serialize(HashSet<string> set)
    {
        // 4 bytes for count, then [4 bytes length + bytes of each string]
        int totalBytes = 4 + 0;
        var utf8 = Encoding.UTF8;
        var stringByteArrays = new List<byte[]>();
        foreach (var str in set)
        {
            byte[] strBytes = utf8.GetBytes(str);
            stringByteArrays.Add(strBytes);
            totalBytes += 4 + strBytes.Length;
        }
        byte[] buffer = new byte[totalBytes];
        int offset = 0;
        BitConverter.GetBytes(set.Count).CopyTo(buffer, offset);
        offset += 4;
        foreach (var strBytes in stringByteArrays)
        {
            BitConverter.GetBytes(strBytes.Length).CopyTo(buffer, offset);
            offset += 4;
            strBytes.CopyTo(buffer, offset);
            offset += strBytes.Length;
        }
        return buffer;
    }

    public static HashSet<string> Deserialize(byte[] buffer)
    {
        var set = new HashSet<string>();
        int offset = 0;
        int count = BitConverter.ToInt32(buffer, offset);
        offset += 4;
        for (int i = 0; i < count; ++i)
        {
            int len = BitConverter.ToInt32(buffer, offset);
            offset += 4;
            string str = Encoding.UTF8.GetString(buffer, offset, len);
            set.Add(str);
            offset += len;
        }
        return set;
    }
}
```
