My own answer to the prompt:

Given the requirements:
- The component should use Shadow DOM.
- Slot structure: header (styled with a bottom border, slightly larger font), intro (always visible), details (only visible when expanded).
- There should be a square button with ‘+’/‘–’ before the header. Clicking this or the header toggles expansion.
- When collapsed, the intro is visible and a button “expand more” is shown below; details are hidden.
- When expanded, details are shown and the expand button is hidden or changes to "collapse".

Here’s how I’d implement it:

```javascript
class XDetails extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({mode: "open"});
    this.expanded = false;
    this.shadowRoot.innerHTML = `
      <style>
        :host { display:block; font-family:inherit; }
        .header {
          display: flex;
          align-items: center;
          cursor: pointer;
          border-bottom: 1px solid #bbb;
          font-size: 1.15em;
          margin-bottom: 0.5em;
        }
        .toggle {
          display: inline-flex;
          width: 22px;
          height: 22px;
          margin-right: 8px;
          align-items:center;
          justify-content:center;
          border: 1px solid #333;
          border-radius: 3px;
          background: #fafafa;
          font-weight:bold;
          user-select: none;
        }
        .intro, .details { margin: 0.5em 0; }
        .expand-btn {
          margin-top: 0.5em;
          padding: 0.3em 0.8em;
          background: #0070ff;
          color: #fff;
          border: none;
          border-radius: 3px;
          cursor: pointer;
        }
      </style>
      <div class="header">
        <span class="toggle" aria-label="Toggle details" tabindex="0">+</span>
        <slot name="header"></slot>
      </div>
      <div class="intro"><slot name="intro"></slot></div>
      <div class="details" hidden>
        <slot name="details"></slot>
      </div>
      <button class="expand-btn">expand more</button>
    `;
  }

  connectedCallback() {
    this.toggleEl = this.shadowRoot.querySelector('.toggle');
    this.detailsEl = this.shadowRoot.querySelector('.details');
    this.expandBtn = this.shadowRoot.querySelector('.expand-btn');
    this.headerEl = this.shadowRoot.querySelector('.header');
    // Toggle expand/collapse on toggle square or header
    this.headerEl.addEventListener('click', (e) => {
      if (e.target === this.expandBtn) return;
      this.toggle();
    });
    this.toggleEl.addEventListener('keydown', (e) => {
      if (e.key === "Enter" || e.key === " ") {
        this.toggle();
        e.preventDefault();
      }
    });
    // Expand button
    this.expandBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggle();
    });
    this.updateUI();
  }

  toggle() {
    this.expanded = !this.expanded;
    this.updateUI();
  }

  updateUI() {
    this.detailsEl.hidden = !this.expanded;
    this.toggleEl.textContent = this.expanded ? "−" : "+";
    this.expandBtn.style.display = this.expanded ? "none" : "inline-block";
  }
}

customElements.define('x-details', XDetails);
```

**Usage:**

```html
<x-details>
  <span slot="header">Header here</span>
  <div slot="intro">Intro part always visible</div>
  <div slot="details">Details, visible when expanded</div>
</x-details>
```

