**My Answer:**

```javascript
class Events {
  constructor() {
    this.subscribers = {};
  }

  subscribe(eventName, callback) {
    if (typeof eventName !== 'string') throw new Error('eventName must be a string');
    if (typeof callback !== 'function') throw new Error('callback must be a function');

    if (!this.subscribers[eventName]) {
      this.subscribers[eventName] = [];
    }
    this.subscribers[eventName].push(callback);
  }

  unsubscribe(eventName, callback) {
    if (!this.subscribers[eventName]) return;
    this.subscribers[eventName] = this.subscribers[eventName].filter(cb => cb !== callback);
    // Optionally remove event name if no subscribers left
    if (this.subscribers[eventName].length === 0) {
      delete this.subscribers[eventName];
    }
  }

  trigger(eventNames, ...options) {
    let names;
    if (typeof eventNames === 'string') {
      // Support either a single event or multiple events in space-separated string
      names = eventNames.split(' ').map(s => s.trim()).filter(Boolean);
    } else if (Array.isArray(eventNames)) {
      names = eventNames;
    } else {
      throw new Error('eventNames must be string or array');
    }

    for (const name of names) {
      const cbs = this.subscribers[name] ? [...this.subscribers[name]] : [];
      cbs.forEach(cb => cb(...options));
    }
  }
}

// Example usage
const events = new Events();
function listener(data) { console.log('Got data:', data); }
events.subscribe('test', listener);
events.trigger('test', { foo: 123 }); // logs: Got data: {foo: 123}
events.unsubscribe('test', listener);
events.trigger('test', { foo: 456 }); // no log
```

