**My answer to the prompt:**

To create a geometry shader in Unity that—given a texture with transparency—will emit one quad *per non-transparent pixel* and extrude each quad by a configurable factor, you generally proceed as follows:

1. **Setup:** Start from a mesh consisting of points (one per texel/pixel) with UV coordinates mapped directly to the texture. You can generate this mesh in C# if needed.
2. **Shader Properties:** Texture with alpha (transparency), extrusion factor, and potentially an alpha threshold.
3. **Vertex Shader:** Pass through vertex position and UVs.
4. **Geometry Shader:** For each input point, sample the texture at the associated UV.
    - If its alpha value >= threshold, output 6 vertices for two triangles forming a quad.
    - The quad should be centered at the input position, with two vertices at the base depth, and the other two extruded along an axis (usually z).
5. **Fragment Shader:** Sample the texture for color preserving transparency (so you get correct blending).

**Sample code:**
```shader
Shader "Custom/ExtrudedQuadGeo"
{
    Properties
    {
        _MainTex("Alpha Texture", 2D) = "white" {}
        _Extrude("Extrude Factor", Float) = 0.1
        _AlphaThresh("Alpha Threshold", Range(0,1)) = 0.1
    }
    SubShader
    {
        Tags{ "RenderType"="Transparent" "Queue"="Transparent"}
        Pass
        {
            CGPROGRAM
            #pragma target 4.0
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Extrude, _AlphaThresh;
            float4 _MainTex_TexelSize;

            struct appdata { float3 vertex: POSITION; float2 uv: TEXCOORD0; };
            struct v2g { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; float3 world : TEXCOORD1; };

            v2g vert(appdata v)
            {
                v2g o;
                o.pos = UnityObjectToClipPos(v.vertex);
                o.uv = v.uv;
                o.world = mul(unity_ObjectToWorld, float4(v.vertex,1)).xyz;
                return o;
            }

            struct g2f { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

            [maxvertexcount(6)]
            void geom(point v2g IN[1], inout TriangleStream<g2f> stream)
            {
                float4 col = tex2D(_MainTex, IN[0].uv);
                if(col.a < _AlphaThresh) return;

                // Compute quad size based on texel size in object/world space:
                float2 size = _MainTex_TexelSize.xy; // In UV space
                float quadSize = 1.0; // You may pass this as parameter

                float3 base = IN[0].world;
                float3 up = float3(0,quadSize*0.5,0), right = float3(quadSize*0.5,0,0);
                float3 extrude = float3(0,0,_Extrude);

                float3 corners[4] = {
                   base - right - up,
                   base + right - up,
                   base + right + up + extrude,
                   base - right + up + extrude
                };
                float2 uvs[4] = {
                   IN[0].uv, IN[0].uv, IN[0].uv, IN[0].uv
                };
                g2f o;
                // Triangle 1
                o.pos = UnityWorldToClipPos(corners[0]); o.uv = uvs[0]; stream.Append(o);
                o.pos = UnityWorldToClipPos(corners[1]); o.uv = uvs[1]; stream.Append(o);
                o.pos = UnityWorldToClipPos(corners[2]); o.uv = uvs[2]; stream.Append(o);
                // Triangle 2
                o.pos = UnityWorldToClipPos(corners[2]); o.uv = uvs[2]; stream.Append(o);
                o.pos = UnityWorldToClipPos(corners[3]); o.uv = uvs[3]; stream.Append(o);
                o.pos = UnityWorldToClipPos(corners[0]); o.uv = uvs[0]; stream.Append(o);
            }

            fixed4 frag(g2f i) : SV_Target
            {
                return tex2D(_MainTex, i.uv);
            }
            ENDCG
        }
    }
    FallBack "Transparent"
}
