    .dark .toolbar, .dark #status, .dark #findbar { background:#232136;color:#eee;}
    .dark #lines{background:#232136;}
    .dark #highlight span.kw { color:#fdc3ff;}
    .dark #highlight span.str { color:#a8ff60;}
    .dark #highlight span.com { color:#77d2a8;}
    .dark #highlight span.num { color:#6cdcff;}
    .dark #highlight span.tag { color:#7da6ff;}
    .dark #highlight span.att { color: #ffb454;}
  </style>
</head>
<body>
  <div class="toolbar">
    <button onclick="newFile()">New</button>
    <button onclick="openFile()">Open</button>
    <button onclick="saveFile()">Save</button>
    <select id="language" onchange="highlightAll()">
      <option value="js">JavaScript</option>
      <option value="html">HTML</option>
      <option value="css">CSS</option>
      <option value="plain">Plain</option>
    </select>
    <button onclick="toggleTheme()">Theme</button>
    <button onclick="showFindBar()">Find/Replace</button>
  </div>
  <div id="findbar">
    Find: <input id="findtext" size="10">
    Replace: <input id="replacetext" size="10">
    <button onclick="findNext()">Next</button>
    <button onclick="doReplace()">Replace</button>
    <button onclick="doReplaceAll()">All</button>
    <button onclick="document.getElementById('findbar').style.display='none'">Close</button>
  </div>
  <div id="container">
    <div id="lines">1</div>
    <div id="wrap">
      <pre id="highlight"></pre>
      <textarea id="editor" spellcheck="false" autocomplete="off"></textarea>
    </div>
  </div>
  <div id="status"></div>
  <input type="file" id="fileinput" style="display:none" />
<script>
// --- Initial --- //
const editor = document.getElementById('editor');
const highlight = document.getElementById('highlight');
const lines = document.getElementById('lines');
const status = document.getElementById('status');
const langSel = document.getElementById('language');

// --- Syntax Highlighting --- //
function doHighlight(code, lang) {
  code = code.replace(/&/g,'&amp;').replace(/</g,'&lt;');
  if(lang === 'plain') return code;
  if(lang === 'js'){
    // comment
    code = code.replace(/(\/\/.*?$|\/\*[\s\S]*?\*\/)/gm, m=>`<span class=com>${m}</span>`);
    // strings
    code = code.replace(/("[^"]*"|'[^']*'|`[^`]*`)/g, m=>`<span class=str>${m}</span>`);
    // keywords
    code = code.replace(/\b(let|var|const|if|else|function|return|for|while|switch|case|break|new|try|catch|throw|class|extends|import|export|from|of|in|typeof|null|undefined|true|false)\b/g, `<span class=kw>$1</span>`);
    // numbers
    code = code.replace(/\b(\d+(\.\d*)?)\b/g, `<span class=num>$1</span>`);
  }
  if(lang === 'css'){
    // comment
    code = code.replace(/(\/\*[\s\S]*?\*\/)/g, m=>`<span class=com>${m}</span>`);
    // strings
    code = code.replace(/("[^"]*"|'[^']*')/g, m=>`<span class=str>${m}</span>`);
    // numbers
    code = code.replace(/\b\d+(px|em|%|rem)?\b/g, m=>`<span class=num>${m}</span>`);
    // css properties (very simple)
    code = code.replace(/(\b[a-z-]+)(?=\s*:)/g, `<span class=kw>$1</span>`);
  }
  if(lang === 'html'){
    // comments
    code = code.replace(/(&lt;!--[\s\S]*?--&gt;)/g, `<span class=com>$1</span>`);
    // tags, attrs
    code = code.replace(/(&lt;\/?)([a-z0-9-]+)(.*?)(\/?&gt;)/gi, (m, a, tag, attr, close) => 
      `${a}<span class=tag>${tag}</span>${attr.replace(/([a-z-]+)=("[^"]*"|'[^']*')/gi, 
        (m,k,v)=>` <span class=att>${k}</span>=<span class=str>${v}</span>`)}${close}`);
  }
  return code;
}
function highlightAll() {
  const val = editor.value, lang = langSel.value;
  highlight.innerHTML = doHighlight(val, lang);
  updateLines();
}
editor.addEventListener('input', highlightAll);

// --- Editor mechanics --- //
function updateLines(){
  let count = editor.value.split('\n').length;
  lines.innerHTML = Array(count).fill(0).map((_,i)=>i+1).join('<br>');
  status.textContent = `Lines: ${count} | Chars: ${editor.value.length} | Words: ${(editor.value.match(/\S+/g)||[]).length}`;
}
editor.addEventListener('input', updateLines);

function syncScroll(){
  highlight.scrollTop = editor.scrollTop;
  lines.scrollTop = editor.scrollTop;
}
editor.addEventListener('scroll', syncScroll);

// --- Auto Indent --- //
editor.addEventListener('keydown', function(e){
  if(e.key==="Tab") {
    e.preventDefault();
    const {selectionStart, selectionEnd, value} = editor;
    editor.value = value.substring(0, selectionStart) + "\t" + value.substring(selectionEnd);
    editor.selectionStart = editor.selectionEnd = selectionStart+1;
    highlightAll();
  }
  if(e.key==="Enter"){
    const pos = editor.selectionStart;
    const val = editor.value, ls = val.lastIndexOf('\n',pos-1)+1;
    const line = val.substring(ls,pos).match(/^\s*/)[0];
    setTimeout(()=> {
      const s = editor.selectionStart;
      editor.value = editor.value.substring(0,s) + line + editor.value.substring(s);
      editor.selectionStart = editor.selectionEnd = s+line.length;
      highlightAll();
    },0);
  }
});

// --- THEME --- //
function toggleTheme(){
  document.body.classList.toggle('dark');
}

// --- Save/Load (localStorage & File) --- //
function saveFile(){
  const blob = new Blob([editor.value],{type:"text/plain"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "notepad-"+Date.now()+".txt";
  document.body.appendChild(a);
  a.click();
  a.remove();
}
function openFile(){
  fileinput.onchange = e => {
    const file = e.target.files[0];
    if(!file) return;
    const fr = new FileReader();
    fr.onload = e2=>{
      editor.value = e2.target.result;
      highlightAll();
    };
    fr.readAsText(file);
  };
  fileinput.value = "";
  fileinput.click();
}
function newFile(){
  if(confirm("Clear editor?")) {
    editor.value = "";
    highlightAll();
  }
}
// Save to localStorage
setInterval(()=>localStorage.setItem('notepadContent', editor.value), 2500);
window.onload = function(){ 
  editor.value = localStorage.getItem('notepadContent')||"";
  highlightAll();
};

// --- Find/Replace --- //
function showFindBar(){
  document.getElementById('findbar').style.display = 'block';
  document.getElementById('findtext').focus();
}
function findNext(){
  let search = document.getElementById('findtext').value;
  if(!search) return;
  let pos = editor.value.indexOf(search, editor.selectionEnd);
  if(pos === -1) pos = editor.value.indexOf(search, 0);
  if(pos !== -1){
    editor.focus();
    editor.selectionStart = pos;
    editor.selectionEnd = pos+search.length;
  }
}
function doReplace(){
  let search = document.getElementById('findtext').value,
      rep = document.getElementById('replacetext').value;
  let start = editor.selectionStart, end = editor.selectionEnd;
  if(editor.value.substring(start, end)===search){
    editor.setRangeText(rep);
    highlightAll();
    findNext();
  }
}
function doReplaceAll(){
  let search = document.getElementById('findtext').value,
      rep = document.getElementById('replacetext').value;
  if(search){
    editor.value = editor.value.split(search).join(rep);
    highlightAll();
  }
}
</script>
</body>
</html>
```
