To display a list of "article" nodes tagged with the taxonomy term 'foobar' using an efficient entity query in Drupal 9 and style the list with Bootstrap 5, you can do the following in a custom Controller or Block:

```php
<?php

use Drupal\Core\Controller\ControllerBase;
use Symfony\Component\DependencyInjection\ContainerInterface;
use Drupal\node\Entity\Node;

/**
 * Example controller for listing articles tagged 'foobar'.
 */
class TeaserArticleListController extends ControllerBase {

  /**
   * Returns a Bootstrap 5 styled list of article teasers tagged 'foobar'.
   */
  public function teaserList() {
    // 1. Load the taxonomy term 'foobar' (optionally restrict to vocabulary).
    $term_storage = $this->entityTypeManager()->getStorage('taxonomy_term');
    $terms = $term_storage->loadByProperties(['name' => 'foobar']);
    if (empty($terms)) {
      // No term found, return an informative message.
      return [
        '#markup' => $this->t('No articles found.'),
      ];
    }
    $term = reset($terms);

    // 2. Efficient entity query: get article nodes tagged with the term.
    $query = $this->entityTypeManager()->getStorage('node')->getQuery();
    $query->condition('status', 1)
      ->condition('type', 'article')
      ->condition('field_tags', $term->id())
      ->sort('created', 'DESC')
      ->accessCheck(TRUE);
    $nids = $query->execute();

    if (empty($nids)) {
      return [
        '#markup' => $this->t('No articles found.'),
      ];
    }

    // 3. Load the nodes & render using the 'teaser' view mode.
    $nodes = Node::loadMultiple($nids);

    $items = [];
    $view_builder = $this->entityTypeManager()->getViewBuilder('node');
    foreach ($nodes as $node) {
      $teaser = $view_builder->view($node, 'teaser');
      $items[] = [
        '#type' => 'container',
        '#attributes' => ['class' => ['list-group-item']],
        'content' => $teaser,
      ];
    }

    // 4. Wrap all teasers in a Bootstrap 5 list group.
    $build = [
      '#type' => 'container',
      '#attributes' => ['class' => ['list-group']],
      'items' => $items,
      '#attached' => [
        // Make sure your theme or a library provides Bootstrap 5.
        'library' => [
          'mytheme/bootstrap5',
        ],
      ],
    ];
    return $build;
  }
}
```

