**userService.ts**
```typescript
import { APIRequestContext } from '@playwright/test';

export interface CreateUserPayload {
  // e.g. name, email, etc.
  name: string;
  email: string;
}

export interface PermissionPayload {
  // e.g. role, permissions, etc.
  role: string;
}

export interface UserCredentials {
  username: string;
  password: string;
}

// Single Responsibility: Handle user operations via API
export class UserService {
  constructor(private readonly request: APIRequestContext) {}

  async createUser(payload: CreateUserPayload): Promise<{ id: string }> {
    const response = await this.request.post('/users/v2/create', { data: payload });
    if (response.status() !== 201) {
      throw new Error(`Failed to create user: ${response.status()}`);
    }
    return response.json();
  }

  async updatePermissions(userId: string, permission: PermissionPayload): Promise<UserCredentials> {
    const payload = { ...permission, id: userId };
    const response = await this.request.post('/users/v2/permissions', { data: payload });
    if (response.status() !== 200) {
      throw new Error(`Failed to update permissions: ${response.status()}`);
    }
    return response.json();
  }

  async createAdminUser(
    createPayload: CreateUserPayload, 
    permissionPayload: PermissionPayload
  ): Promise<UserCredentials> {
    const user = await this.createUser(createPayload);
    return this.updatePermissions(user.id, permissionPayload);
  }
}
```

