```javascript
import { defineStore } from 'pinia';

export const useTableStore = defineStore('table', {
  state: () => ({
    rows: [],
    total: 0,
    loading: false,
  }),
  actions: {
    async fetchRows(start = 0, count = 20) {
      if (this.loading) return;
      this.loading = true;
      try {
        const res = await fetch(`/api/rows?start=${start}&count=${count}`);
        const json = await res.json();
        if (start === 0) {
          this.rows = json.rows;
        } else {
          this.rows.push(...json.rows);
        }
        this.total = json.total ?? this.total; // prefer total from API if available
      } catch (e) {
        console.error(e);
      } finally {
        this.loading = false;
      }
    },
  },
});
```

**2. Infinite Scroll Table (components/InfiniteTable.vue):**
