  const el = scrollParent.value;
  if (!el) return;
  // Check if scrolled to within 100px of bottom
  if (
    el.scrollTop + el.clientHeight >= el.scrollHeight - 100 &&
    !store.loading &&
    store.rows.length < store.total
  ) {
    store.fetchRows(store.rows.length, PAGE_SIZE);
  }
};

onMounted(() => {
  store.fetchRows(0, PAGE_SIZE);
});
</script>

