**Ideal Solution Outline**

This problem asks for the union area of axis-aligned rectangles with large coordinates. The standard approach is a scanline algorithm combined with interval/segment merging or line segment tree. Since n is up to 50, it's feasible to:
- Use a scanline over the x-axis, process all events at rectangle sides.
- For each vertical slab between two adjacent x values, maintain a set of y-intervals and merge them to find the covered length on the y-axis. Multiply it by the x-interval width to get area increment.

Another high-performance approach is to use coordinate compression (discretization) on the y-coordinates and use a segment tree to quickly update and query the covered y-length as the x scan sweeps through events.

Here's perfect C++ code using scanline + interval merging (since the constraints are small, this is simple and robust):

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;
typedef long long ll;

const int MOD = 1e9 + 7;

int main() {
    int n;
    cin >> n;
    vector<vector<ll>> rects(n, vector<ll>(4));
    vector<ll> xs; // all unique x coordinates
    for (int i = 0; i < n; ++i) {
        cin >> rects[i][0] >> rects[i][1] >> rects[i][2] >> rects[i][3];
        xs.push_back(rects[i][0]);
        xs.push_back(rects[i][2]);
    }
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());

    ll res = 0;
    for (size_t i = 1; i < xs.size(); ++i) {
        ll xl = xs[i-1], xr = xs[i];
        if (xl == xr) continue;
        vector<pair<ll, ll>> intervals;
        for (const auto& r : rects) {
            if (r[0] <= xl && r[2] >= xr) {
                intervals.emplace_back(r[1], r[3]);
            }
        }
        if (intervals.empty()) continue;
        sort(intervals.begin(), intervals.end());
        ll total_y = 0, cur_l = -1, cur_r = -1;
        for (const auto& [l, r] : intervals) {
            if (r <= l) continue;
            if (l > cur_r) {
                total_y += cur_r - cur_l;
                cur_l = l;
                cur_r = r;
            } else {
                cur_r = max(cur_r, r);
            }
        }
        total_y += cur_r - cur_l;
        res = (res + (xr - xl) % MOD * (total_y % MOD)) % MOD;
    }
    cout << res << "\n";
    return 0;
}
```
- This accumulates the area as scanline passes between x slabs, merges and counts the covered y-intervals.

