**My Answer:**

To solve the problem of calculating the total area covered by several axis-aligned rectangles (with potential overlap counted only once), an efficient solution is required due to the large coordinate values.

A sweep line approach with segment tree + coordinate compression (discretization) on the y-axis is ideal since there are at most 50 rectangles but coordinates may be up to 1e9. The following is a C++ solution, clearly commented:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;

struct Event {
    ll x;
    int y1, y2; // indices after y-coord discretization
    int type;   // +1 for entering, -1 for leaving
    Event(ll x, int y1, int y2, int type) : x(x), y1(y1), y2(y2), type(type) {}
    bool operator<(const Event& other) const { return x < other.x; }
};

struct SegmentTree {
    int n;
    vector<int> count;
    vector<ll> len;
    vector<ll> ys;
    SegmentTree(const vector<ll>& ys_) : ys(ys_) {
        n = ys.size() - 1;
        count.assign(4 * n, 0);
        len.assign(4 * n, 0);
    }
    void update(int node, int l, int r, int ql, int qr, int val) {
        if (ql >= r || qr <= l) return;
        if (ql <= l && r <= qr) {
            count[node] += val;
        } else {
            int m = (l + r) / 2;
            update(node * 2, l, m, ql, qr, val);
            update(node * 2 + 1, m, r, ql, qr, val);
        }
        if (count[node]) {
            len[node] = ys[r] - ys[l];
        } else if (r - l == 1) {
            len[node] = 0;
        } else {
            len[node] = len[node * 2] + len[node * 2 + 1];
        }
    }
};

int main() {
    int n;
    cin >> n;
    vector<vector<ll>> rects(n, vector<ll>(4));
    vector<ll> ycoords;
    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        cin >> rects[i][0] >> rects[i][1] >> rects[i][2] >> rects[i][3];
        ll x1 = rects[i][0], y1 = rects[i][1];
        ll x2 = rects[i][2], y2 = rects[i][3];
        events.emplace_back(x1, 0, 0, 1); // y1/y2 to be filled after discretization
        events.emplace_back(x2, 0, 0, -1);
        ycoords.push_back(y1);
        ycoords.push_back(y2);
    }
    sort(ycoords.begin(), ycoords.end());
    ycoords.erase(unique(ycoords.begin(), ycoords.end()), ycoords.end());
    // Discretize y for each event
    for (int i = 0, k = 0; i < n; ++i) {
        ll x1 = rects[i][0], y1 = rects[i][1], x2 = rects[i][2], y2 = rects[i][3];
        int l = lower_bound(ycoords.begin(), ycoords.end(), y1) - ycoords.begin();
        int r = lower_bound(ycoords.begin(), ycoords.end(), y2) - ycoords.begin();
        events[2 * i].y1 = l; events[2 * i].y2 = r;
        events[2 * i + 1].y1 = l; events[2 * i + 1].y2 = r;
    }
    sort(events.begin(), events.end());
    SegmentTree st(ycoords);
    ll ans = 0;
    ll prevx = events[0].x;
    for (const auto& e : events) {
        ll curx = e.x;
        ll width = curx - prevx;
        if (width > 0) {
            ans = (ans + width % MOD * st.len[1] % MOD) % MOD;
        }
        st.update(1, 0, st.n, e.y1, e.y2, e.type);
        prevx = curx;
    }
    cout << ans << endl;
    return 0;
}
```

**Explanation:**

- Each rectangle gives rise to two events: its left (enter) and right (exit) edges. 
- The y-axis is discretized so the sweep can run efficiently.
- For each event (from left to right), update the segment tree for the interval [y1, y2).
- The segment tree always knows the union of covered y-lengths, so we multiply by the x-difference swept.
- Modulo 1e9+7 is taken.

