```java
import java.util.*;

public class StairSteps {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("请输入台阶数 n：");
        int n = sc.nextInt();
        List<List<Integer>> solutions = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
