        for (List<Integer> s : solutions) {
            System.out.println(s);
        }
    }
    private static void dfs(int n, List<Integer> path, List<List<Integer>> solutions) {
        if (n == 0) {
            solutions.add(new ArrayList<>(path));
            return;
        }
        if (n < 0)
            return;
        path.add(1);
        dfs(n-1, path, solutions);
        path.remove(path.size() - 1);
        path.add(2);
        dfs(n-2, path, solutions);
        path.remove(path.size() - 1);
    }
}
```
