```c
#include <stdio.h>

// Hàm mở rộng Euclid: tìm d = gcd(a, b), x, y sao cho ax + by = d
int extendedEuclid(int a, int b, int *x, int *y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }

    int x2 = 1, x1 = 0; // x2 ứng với hệ số a, x1 ứng với hệ số b
    int y2 = 0, y1 = 1;
    int q, r, x_temp, y_temp;

    while (b > 0) {
        q = a / b;
        r = a - q * b;

        x_temp = x2 - q * x1;
        y_temp = y2 - q * y1;

        a = b;
        b = r;

        x2 = x1;
        x1 = x_temp;
        y2 = y1;
        y1 = y_temp;
    }

    *x = x2;
    *y = y2;
    return a;
}

int main() {
    int a, b, d, x, y;
    printf("Nhap a, b: ");
    scanf("%d%d", &a, &b);

    d = extendedEuclid(a, b, &x, &y);

    printf("gcd(%d, %d) = %d\n", a, b, d);
    printf("He so x = %d, y = %d\n", x, y);
    printf("Kiem tra: %d*%d + %d*%d = %d\n", a, x, b, y, a * x + b * y);
    return 0;
}
```

